// against plus a margin, never less than the margin alone and never more than
// the ceiling: a fixed bound stopped every closeout once a repository's
// committed tree outgrew it (spec pose-git-snapshot-budget-scales-with-the-tree).
var (
	gitSnapshotMarginBytes  int64 = 256 << 20
	gitSnapshotCeilingBytes int64 = 4 << 30
)

func gitSnapshotBudget(committedBytes int64) int64 {
	if committedBytes < 0 {
		committedBytes = 0
	}
	if committedBytes > gitSnapshotCeilingBytes-gitSnapshotMarginBytes {
		return gitSnapshotCeilingBytes
	}
	return committedBytes + gitSnapshotMarginBytes
}

// A committed tree listing is read through a bounded buffer under a
// deadline: 100,000 entries of ordinary paths fit well inside it, and a
// listing past it fails closed before it is retained (review N2).
var (
	gitTreeListingMaxBytes int64 = 64 << 20
	gitTreeListingTimeout        = 2 * time.Minute
)

// listCommittedTree returns `ls-tree -r -l -z commit` of root, bounded.
func listCommittedTree(root, commit string) ([]byte, error) {
	ctx, cancel := context.WithTimeout(context.Background(), gitTreeListingTimeout)
	defer cancel()
	return runGovernanceGitCommandContext(ctx, NativeFiles(), root, []string{"ls-tree", "-r", "-l", "-z", commit}, gitTreeListingMaxBytes)
}

// gitCommittedTreeBytes sums the blob sizes of an `ls-tree -r -l -z` listing.
func gitCommittedTreeBytes(listing []byte) int64 {
	var total int64
	for _, record := range bytes.Split(listing, []byte{0}) {
		i := bytes.IndexByte(record, '\t')
		if i < 0 {
			continue
		}
		fields := strings.Fields(string(record[:i]))
		if len(fields) == 4 {
			if size, err := strconv.ParseInt(fields[3], 10, 64); err == nil && size > 0 {
				total += size
			}
		}
	}
	return total
}

// Snapshot disk, including ignored files. Git status alone cannot witness
// creation of an ignored output. WalkDir never follows a directory symlink.
func dispatchDiskSnapshot(root string) (map[string]string, error) {
	entries := map[string]string{}
	var total int64
	committed := int64(0)
	if listing, err := listCommittedTree(root, "HEAD"); err == nil {
		committed = gitCommittedTreeBytes(listing)
	}
	budget := gitSnapshotBudget(committed)
	err := filepath.WalkDir(root, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		if rel == "." {
			return nil
		}
		if rel == ".git" {
			if entry.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		info, err := entry.Info()
		if err != nil {
			return err
		}
		// The per-root authority lock is runtime coordination state, not a
		// project input. Ignore only the exact regular file: a linked or special
		// replacement remains visible to the snapshot and fails closed.
		if filepath.ToSlash(rel) == ".pose/transfers/.authority-transfer.lock" && info.Mode().IsRegular() {
			return nil
		}
		if len(entries) >= 100000 {
			return fmt.Errorf("disk snapshot exceeds 100000 entries")
		}
		hash := sha256.New()
		fmt.Fprintf(hash, "%s\x00", info.Mode().String())
		switch {
		case info.Mode().IsRegular():
			file, err := os.Open(path)
			if err != nil {
				return err
			}
			n, readErr := io.Copy(hash, io.LimitReader(file, budget-total+1))
			closeErr := file.Close()
			total += n
			if readErr != nil {
				return readErr
			}
			if closeErr != nil {
				return closeErr
			}
			if total > budget {
				return fmt.Errorf("disk snapshot exceeds its budget of %d bytes", budget)
			}
		case info.Mode()&os.ModeSymlink != 0:
			target, err := os.Readlink(path)
			if err != nil {
				return err
			}
			hash.Write([]byte(target))
		case info.IsDir():
		default:
			return fmt.Errorf("unsupported file type at %q", rel)
		}
		entries[filepath.ToSlash(rel)] = hex.EncodeToString(hash.Sum(nil))
		return nil
	})
	if err != nil {
		return nil, &GitSnapshotError{"disk snapshot", err}
	}
	return entries, nil
}

